try {const v=JSON.parse(localStorage.getItem(key));records=Array.isArray(v)&&v.every(r=>r&&typeof r.id==='string'&&/^[a-z0-9-]+$/i.test(r.id)&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&moduleBy(r.module)&&typeof r.title==='string'&&Array.isArray(r.history))?v:seeds();}catch{records=seeds();}
let route, page=1, pageSize=6, query='', sort='date', descending=true, start='', end='', actionFilter='All', dashboardTab='To review', draft=null, dirty=false, oldHash=location.hash, storageError=false;
