function parseRoute(){const [base,qs='']=(location.hash.slice(1)||'signin').split('?');const [view,id]=base.split('/');return {view,id,tab:new URLSearchParams(qs).get('tab')||'All'};}
function modal(title,content,cls=''){
 lastFocus=document.activeElement;dialog.className=cls;dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('x')}</button></div>${content}`;
 translatePage(dialog,language);if(!dialog.open)dialog.showModal();icons();
}
function closeModal(){dialog.close();lastFocus?.focus();}
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
dialog.addEventListener('close',()=>lastFocus?.focus());

