function heading(title,subtitle,action=''){return `<section class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</section>`;}
const createButton=id=>`<button class="button primary" data-action="create" data-module="${id||''}">${icon('plus')}<span>${id==='certificates'?'New thank you card':id==='uniforms'?'New uniform request':id==='ideas'?'New idea':'Create document'}</span></button>`;
function dashboard(){
 const stats=[['To review','Needs your attention','inbox'],['Draft','Pick up where you left off','file-pen-line'],['Returned','Ready for your updates','corner-up-left'],['In review','With your reviewers','clock-3']];
 const todo=records.filter(r=>r.status===dashboardTab);
 return heading(`${greeting()}, ${esc(currentUser.first)}<span class="greeting-dot">.</span>`,t('subtitle'),`<div class="heading-date">${icon('calendar-days')}<span>${new Intl.DateTimeFormat(localeFor(language),{weekday:'short',day:'numeric',month:'long',year:'numeric'}).format(new Date())}</span></div>`)+
 `<section class="overview-stats" aria-label="Your document status">${stats.map(([status,desc,ic])=>`<button class="stat" data-action="stat" data-tab="${status}"><span class="stat-top">${status}${icon(ic)}</span><span class="stat-number">${String(records.filter(r=>r.status===status).length).padStart(2,'0')}</span><span class="stat-bottom">${desc}${icon('arrow-up-right')}</span></button>`).join('')}</section>
 <div class="dashboard-grid"><div class="dashboard-primary"><section class="surface attention"><div class="section-heading"><div><h2>${t('next')}</h2><p>${t('nextSub')}</p></div><span class="subtle-icon">${icon('list-todo')}</span></div><div class="tabs" role="tablist" aria-label="Priority work">${['To review','Draft','Returned'].map(t=>`<button role="tab" aria-selected="${t===dashboardTab}" class="tab ${t===dashboardTab?'selected':''}" data-action="dashboard-tab" data-tab="${t}">${t==='Draft'?'Drafts':t}<span>${records.filter(r=>r.status===t).length}</span></button>`).join('')}</div>
 <div class="task-list">${todo.length?todo.slice(0,4).map(r=>`<a class="task-row" href="#${r.status==='Draft'||r.status==='Returned'?'compose/'+r.module+'?edit='+r.id:'document/'+r.id}"><span class="doc-icon ${r.module==='business'?'blue':''}">${icon(moduleBy(r.module).icon)}</span><span class="task-copy"><strong>${esc(r.title)}</strong><small>${moduleBy(r.module).name}<span>·</span>${esc(r.owner)}</small></span><span class="task-date">${pretty(r.date)}</span>${icon('chevron-right')}</a>`).join(''):empty('You’re all caught up','There are no documents in this queue.')}</div>
 <div class="section-footer"><span>${todo.length} ${todo.length===1?'document':'documents'} ${dashboardTab==='To review'?'waiting for your review':dashboardTab==='Draft'?'ready to continue':'ready for updates'}</span><button class="text-button" data-action="all-documents" data-tab="${dashboardTab}">View all ${icon('arrow-right')}</button></div></section>
 <section class="surface recent"><div class="section-heading"><div><h2>${t('recent')}</h2><p>${t('recentSub')}</p></div><button class="text-button" data-action="all-documents" data-tab="History">View history ${icon('arrow-right')}</button></div>${[...records].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(r=>`<a class="activity-row" href="#document/${r.id}"><span class="activity-point ${statusClass(r.status)}">${icon(r.status==='Approved'?'check':r.status==='Draft'?'pencil':'file-check-2')}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.history.at(-1)?.action||r.status)} <span>·</span> ${pretty(r.date)}</small></span>${badge(r.status)}</a>`).join('')}</section></div>
 <aside class="dashboard-secondary"><section class="quick-create"><div class="section-heading"><div><h2>${t('make')}</h2><p>${t('makeSub')}</p></div></div>${[['memo','Write an internal memo','Share an update or request'],['business','Create a business case','Put your proposal forward'],['ideas','Share an innovative idea','Make room for a better way']].map(([id,title,desc])=>`<button class="quick-action" data-action="create" data-module="${id}"><span class="quick-icon">${icon(moduleBy(id).icon)}</span><span><strong>${title}</strong><small>${desc}</small></span>${icon('arrow-up-right')}</button>`).join('')}<button class="quick-all" data-action="create">Explore all document types ${icon('arrow-right')}</button></section>
 <section class="recognition"><span class="recognition-art">${icon('hand-heart')}</span><h2>A small thank you.<br>A meaningful moment.</h2><p>Recognise the people who make a difference to your day.</p><button class="button" data-action="create" data-module="certificates">Create a thank you card ${icon('arrow-right')}</button></section>
 <div class="workspace-note">${icon('shield-check')}<p>A workspace built around<br>the way you work.</p></div></aside></div>
 <section class="surface document-summary"><div class="section-heading"><div><h2>Your documents at a glance</h2><p>The same workflows, with a clearer overview.</p></div></div><div class="table-scroll"><table><thead><tr><th>Document type</th><th>To review</th><th>Drafts</th><th>Returned</th><th>In review</th><th><span class="sr-only">Open module</span></th></tr></thead><tbody>${MODULES.filter(m=>m.group==='Documents').map(m=>`<tr><td><a class="module-link" href="#module/${m.id}">${icon(m.icon)}${m.name}</a></td>${['To review','Draft','Returned','In review'].map(t=>`<td><a class="count-link" href="#module/${m.id}?tab=${encodeURIComponent(t)}">${records.filter(r=>r.module===m.id&&r.status===t).length}</a></td>`).join('')}<td><a class="icon-button" href="#module/${m.id}" aria-label="Open ${m.name}">${icon('chevron-right')}</a></td></tr>`).join('')}</tbody></table></div></section>`;
}
function empty(title,desc,action=''){return `<div class="empty-state">${icon('inbox')}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`;}
function tabsFor(id){if(id==='ideas')return ['All','In review','Returned','Draft','History'];if(id==='uniforms')return ['All','Draft','Submitted','History'];if(id==='certificates')return ['All','History'];if(id==='incoming')return ['All','To review','Received','Draft','Archived','History'];if(id==='invoices')return ['All','Approved','History'];if(id==='duties')return ['All'];return ['All','To review','Draft','In review','Returned','Received','Archived','History','Reports'];}
function currentRows(){return selectRecords(records,{module:route.view==='module'?route.id:undefined,tab:actionFilter==='All'?route.tab:actionFilter,query,start,end,sort,descending});}
function listing(){const m=moduleBy(route.id),all=route.view==='documents';if(!m&&!all)return notFound();
 const title=all?'All documents':m.plural;return heading(esc(title),all?'Find and follow work across your workspace.':m.desc,m?.id==='duties'||m?.id==='invoices'?'':createButton(m?.id))+
 `<section class="surface list-surface">${m?.id==='duties'?'<div class="inline-note">Duty assignments will appear here when available.</div>':''}<div class="tabs scroll-tabs" role="tablist" aria-label="Document status">${(all?['All','To review','Draft','In review','Returned','History']:tabsFor(m.id)).map(t=>`<a role="tab" aria-selected="${route.tab===t}" href="#${all?'documents':'module/'+m.id}?tab=${encodeURIComponent(t)}" class="tab ${route.tab===t?'selected':''}">${t==='Draft'?'Drafts':t}<span>${t==='All'||t==='History'||t==='Reports'?records.filter(r=>all||r.module===m.id).length:records.filter(r=>(all||r.module===m.id)&&r.status===t).length}</span></a>`).join('')}</div>
 <div class="table-controls"><label class="table-search">${icon('search')}<input type="search" id="table-query" placeholder="Search ${esc(title.toLowerCase())}" value="${esc(query)}" aria-label="Search documents"></label><div class="table-control-buttons"><button class="button small" data-action="filters">${icon('sliders-horizontal')} Filters</button><button class="button small" data-action="export">${icon('download')} Export</button></div></div>
 <div id="active-filters">${start||end||actionFilter!=='All'?`<p class="filter-summary">${start?'From '+esc(start):''} ${end?'to '+esc(end):''} ${actionFilter!=='All'?esc(actionFilter):''}<button data-action="clear-filters">Clear filters ${icon('x')}</button></p>`:''}</div><div id="records-table">${tableContent()}</div></section>`;}
function tableContent(){const rows=currentRows(),limit=pageSize,total=Math.max(1,Math.ceil(rows.length/limit));page=Math.min(page,total);const list=rows.slice((page-1)*limit,page*limit);const special=route.id;
 const heads=special==='invoices'?[['title','Vendor / invoice'],['owner','Bank contact'],['po','Purchase order'],['amount','Amount / VAT'],['date','Invoice date']]:special==='ideas'?[['title','Idea / reference'],['category','Category / segment'],['assignee','Assignee'],['date','Created'],['status','Status']]:[['title',special==='certificates'?'Card / recipient':'Document / reference'],['owner','Created by'],['date','Created'],['status','Status']];
 return `<div class="table-scroll"><table class="records-table"><thead><tr>${heads.map(([key,label])=>`<th aria-sort="${sort===key?(descending?'descending':'ascending'):'none'}"><button data-action="sort" data-sort="${key}">${label}${icon(sort===key?(descending?'arrow-down':'arrow-up'):'chevrons-up-down')}</button></th>`).join('')}<th>Action</th></tr></thead><tbody>${list.map(r=>`<tr><td><a class="table-title" href="#document/${r.id}"><span class="mini-doc-icon">${icon(moduleBy(r.module).icon)}</span><span><strong>${esc(special==='invoices'?r.vendor:r.title)}</strong><small>${esc(special==='certificates'?r.recipient:special==='invoices'?r.invoiceNumber:r.reference)}</small></span></a></td>${special==='invoices'?`<td>${esc(r.contact)}</td><td>${esc(r.po)}</td><td>TZS ${Number(r.amount||0).toLocaleString()}<small>VAT ${Number(r.vat||0).toLocaleString()}</small></td><td>${pretty(r.date)}</td>`:special==='ideas'?`<td>${esc(r.category)}<small>${esc(r.segment)}</small></td><td>${esc(r.assignee)}</td><td>${pretty(r.date)}</td><td>${badge(r.status)}</td>`:`<td><span class="owner-cell"><span class="tiny-avatar">${esc(r.owner.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>${esc(r.owner)}</span></td><td>${pretty(r.date)}</td><td>${badge(r.status)}</td>`}<td><a class="row-action" href="#${r.status==='Draft'||r.status==='Returned'?'compose/'+r.module+'?edit='+r.id:'document/'+r.id}">${r.status==='Draft'||r.status==='Returned'?'Continue':'View'} ${icon('chevron-right')}</a></td></tr>`).join('')}</tbody></table></div>${!list.length?empty('No documents here yet',query||start||end?'Try another search or clear your filters.':'Documents will appear here as work moves through this stage.'):''}<div class="pagination"><label>Show <select id="page-size" aria-label="Rows per page">${[6,10,25].map(n=>`<option ${pageSize===n?'selected':''}>${n}</option>`).join('')}</select> per page</label><span>${rows.length?(page-1)*limit+1:0}–${Math.min(page*limit,rows.length)} of ${rows.length}</span><div><button class="icon-button" data-action="previous" aria-label="Previous page" ${page===1?'disabled':''}>${icon('chevron-left')}</button><span class="page-number">${page}</span><button class="icon-button" data-action="next" aria-label="Next page" ${page>=total?'disabled':''}>${icon('chevron-right')}</button></div></div>`;}
function refreshTable(){const el=$('#records-table');if(el){el.innerHTML=tableContent();translatePage(el,language);icons();}}
function sanitise(html){const root=new DOMParser().parseFromString(String(html),'text/html');const allowed=new Set(['P','BR','STRONG','B','EM','I','U','UL','OL','LI','H2','H3','BLOCKQUOTE','A','DIV']);function clean(node){if(node.nodeType===3)return document.createTextNode(node.textContent);if(node.nodeType!==1)return document.createTextNode('');if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH'].includes(node.tagName))return document.createTextNode('');const el=document.createElement(allowed.has(node.tagName)?node.tagName.toLowerCase():'span');if(node.tagName==='A'){const h=node.getAttribute('href')||'';if(/^https?:\/\//i.test(h)){el.setAttribute('href',h);el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');}}for(const child of node.childNodes)el.append(clean(child));return el;}const out=document.createElement('div');for(const child of root.body.childNodes)out.append(clean(child));return out.innerHTML;}
function field(name,label,type='text',value='',extra=''){return `<div class="field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" aria-describedby="error-${name}" ${extra}><small id="error-${name}" class="field-error" data-error="${name}"></small></div>`;}
function formView(){const m=moduleBy(route.id);if(!m)return notFound();const params=new URLSearchParams((location.hash.split('?')[1]||'')),edit=params.get('edit'),template=MEMO_TEMPLATES.find(item=>item.id===params.get('template'));if(!draft||draft.module!==route.id||draft.edit!==edit){const existing=records.find(r=>r.id===edit);draft={...(existing||{id:crypto.randomUUID(),module:m.id,title:template?.title||'',status:'Draft',owner:currentUser.name,date:today(),classification:template?.classification||'Internal',to:template?.to||'',from:currentUser.name,ufs:template?.ufs||'',body:template?.body||'',history:[],recipient:'',category:'Service improvement',segment:'All customers',businessCategory:'Digital services',uniform:'HQ staff uniform',size:'M',attachment:''}),edit};dirty=false;}
 const isCard=m.id==='certificates',isUniform=m.id==='uniforms',isIdea=m.id==='ideas';
 return `<a class="back-link" href="#module/${m.id}">${icon('arrow-left')} Back to ${m.plural.toLowerCase()}</a>`+heading(`${edit?'Edit':'New'} ${isCard?'thank you card':isUniform?'uniform request':isIdea?'innovative idea':m.name.toLowerCase()}`,isCard?'Make someone’s contribution feel seen.':'A focused space to prepare your next submission.',`<span class="save-status" id="save-status">${icon('circle')} ${edit?'Saved draft':'Not saved yet'}</span>`)+
 `<form id="document-form" novalidate><div class="form-grid"><section class="surface editor-surface"><div class="form-section"><h2>${isCard?'Your message':'Document details'}</h2><div id="form-errors" class="error-summary" role="alert" hidden></div>
 ${field('title',isCard?'Card title':'Subject <span class="required">*</span>','text',draft.title,'maxlength="180" required')}
 ${isCard?field('recipient','Colleague’s name <span class="required">*</span>','text',draft.recipient,'required'):isUniform?`<div class="field-grid">${field('uniform','Uniform','text',draft.uniform)}<label class="field"><span>Size</span><select name="size">${['XS','S','M','L','XL','XXL'].map(s=>`<option ${draft.size===s?'selected':''}>${s}</option>`).join('')}</select></label></div>`:`<div class="field-grid">${field('to','To <span class="required">*</span>','text',draft.to,'list="colleagues" placeholder="Choose or enter a recipient"')}${field('from','From','text',draft.from)}</div>${field('ufs','Ufs','text',draft.ufs,'placeholder="Add routing details, if required"')}<datalist id="colleagues"><option>Department Head</option><option>Finance team</option><option>Procurement team</option><option>Marketing team</option></datalist>`}
 ${isIdea?`<div class="field-grid">${field('category','Idea category','text',draft.category)}${field('segment','Customer segment','text',draft.segment)}${field('businessCategory','Business category','text',draft.businessCategory)}</div>`:''}</div>
 <div class="form-section body-section"><label id="body-label">${isCard?'Description':isUniform?'Additional notes':'Body'} ${!isUniform?'<span class="required">*</span>':''}</label><div class="rich-editor"><div class="editor-toolbar" role="toolbar" aria-label="Text formatting">${[['bold','bold','Bold'],['italic','italic','Italic'],['underline','underline','Underline'],['insertUnorderedList','list','Bulleted list'],['insertOrderedList','list-ordered','Numbered list'],['undo','undo-2','Undo'],['redo','redo-2','Redo']].map(([cmd,ic,title])=>`<button type="button" class="icon-button" data-action="format" data-command="${cmd}" aria-label="${title}" title="${title}">${icon(ic)}</button>`).join('')}</div><div id="body-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-labelledby="body-label" aria-describedby="error-body" data-placeholder="${isCard?'Tell your colleague what you appreciate…':'Start writing here…'}">${sanitise(draft.body)}</div><div class="editor-bottom"><span>Formatting stays with your document</span><span id="word-count">${draft.body.replace(/<[^>]*>/g,' ').trim().split(/\s+/).filter(Boolean).length} words</span></div></div><small id="error-body" class="field-error" data-error="body"></small></div>
 ${!isCard?`<div class="form-section attachment-section"><label class="attachment-zone">${icon('paperclip')}<span><strong id="attachment-name">${esc(draft.attachment||'Attach a supporting document')}</strong><small>PDF, Word or image · Up to 10 MB · Preview records the filename</small></span><input id="attachment" type="file" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg"><span class="button small">Choose file</span></label><p id="attachment-error" role="alert"></p></div>`:''}</section>
 <aside class="form-aside"><section class="surface details-panel"><h2>At a glance</h2><div class="detail-pair"><span>Owner</span><strong>${esc(currentUser.name)}</strong></div>${field('date','Date','date',draft.date)}<label class="field"><span>Classification</span><select name="classification">${['Open','Internal','Confidential','Restricted'].map(v=>`<option value="${v}" ${v===draft.classification?'selected':''}>${v}</option>`).join('')}</select></label><div class="detail-pair"><span>Document type</span><strong>${m.name}</strong></div><div class="detail-pair"><span>Status</span>${badge(draft.status)}</div></section><div class="writing-note">${icon('sparkles')}<h3>A little clarity goes a long way</h3><p>Use a specific subject. Give your reader the context they need and make the next step clear.</p></div></aside></div>
 <div class="form-actions"><a class="button ghost" href="#module/${m.id}">Cancel</a><div><button class="button" type="submit" name="intent" value="draft">${icon('save')} Save draft</button><button class="button primary" type="submit" name="intent" value="submit">${isCard?'Save card':isUniform?'Submit request':'Submit for review'} ${icon('arrow-right')}</button></div></div></form>`;}
function readDraft(){if(!draft)return;const form=$('#document-form');if(!form)return;for(const [k,v]of new FormData(form))if(k!=='intent')draft[k]=v;draft.body=sanitise($('#body-editor').innerHTML);}
function documentView(){const r=records.find(r=>r.id===route.id);if(!r)return notFound();const m=moduleBy(r.module);
 const actions=r.status==='To review'?`<button class="button" data-action="return" data-id="${r.id}">${icon('corner-up-left')} Return with feedback</button><button class="button primary" data-action="approve" data-id="${r.id}">${icon('check')} Approve</button>`:r.status==='Draft'||r.status==='Returned'?`<a class="button primary" href="#compose/${r.module}?edit=${r.id}">${icon('pencil')} Edit document</a>`:r.status==='In review'?`<button class="button" data-action="withdraw" data-id="${r.id}">Withdraw to draft</button>`:r.status!=='Archived'?`<button class="button" data-action="archive" data-id="${r.id}">${icon('archive')} Archive</button>`:'';
 return `<a class="back-link" href="#module/${m.id}">${icon('arrow-left')} Back to ${m.plural.toLowerCase()}</a>`+heading(esc(r.title),`${m.name} · ${esc(r.reference)}`,`<button class="button" data-action="print">${icon('printer')} Print / Save PDF</button>`)+
 `<div class="document-grid"><article class="surface document-paper ${r.module==='certificates'?'certificate-paper':''}">${r.module==='certificates'?`<div class="certificate-mark">${icon('award')}</div><p class="bank-name">CRDB Bank</p><h2>Thank you, ${esc(r.recipient)}</h2>`:`<div class="paper-heading"><strong>CRDB Bank</strong>${badge(r.status)}</div><h2>${esc(r.title)}</h2><div class="paper-meta"><p><span>To</span>${esc(r.to||'—')}</p><p><span>From</span>${esc(r.from||r.owner)}</p>${r.ufs?`<p><span>Ufs</span>${esc(r.ufs)}</p>`:''}<p><span>Date</span>${pretty(r.date)}</p><p><span>Classification</span>${esc(r.classification)}</p></div>`}
 ${r.module==='uniforms'?`<div class="uniform-summary"><h3>Staff uniform request</h3><p>Staff name: ${esc(r.owner)}</p><p>Department: ${esc(currentUser.department)}</p><p>Uniform: ${esc(r.uniform)}</p><p>Size: ${esc(r.size)}</p></div>`:''}
 ${r.module==='invoices'?`<dl class="invoice-summary"><dt>Vendor</dt><dd>${esc(r.vendor)}</dd><dt>Bank contact</dt><dd>${esc(r.contact)}</dd><dt>Purchase order</dt><dd>${esc(r.po)}</dd><dt>Invoice</dt><dd>${esc(r.invoiceNumber)}</dd><dt>Amount</dt><dd>TZS ${Number(r.amount).toLocaleString()}</dd><dt>VAT</dt><dd>TZS ${Number(r.vat).toLocaleString()}</dd></dl>`:''}
 <div class="document-body">${sanitise(r.body)}</div>${r.attachment?`<div class="document-attachment">${icon('paperclip')} ${esc(r.attachment)} <small>Filename only in this preview</small></div>`:''}</article>
 <aside><section class="surface details-panel"><h2>Document progress</h2>${badge(r.status)}<ol class="timeline">${r.history.map(h=>`<li><strong>${esc(h.action)}</strong><small>${esc(h.by)}<br>${pretty(h.date)}</small>${h.note?`<p>${esc(h.note)}</p>`:''}</li>`).join('')}</ol></section></aside></div><div class="form-actions"><a class="button ghost" href="#module/${m.id}">Back to list</a><div>${actions}</div></div>`;}
function notFound(){return empty('This page is not available','Go back to your overview to find your work.','<a class="button primary" href="#dashboard">Back to overview</a>');}
function authView(otp=false){return `<main class="auth-page" id="main"><div class="auth-story"><a class="brand" href="#signin">${logo()}</a><div class="auth-headline"><span class="auth-line"></span><h1>I play my part,<br>We win together.</h1></div><span class="auth-footer">One Bank. One Team. One Shared Success.</span></div><div class="auth-form-wrap"><div class="auth-form"><div class="auth-utilities"><button class="language-button" data-action="language">${icon('languages')}<span>${language.toUpperCase()}</span></button><button class="icon-button" data-action="theme" aria-label="${t('theme')}">${icon(theme==='dark'?'sun':'moon')}</button></div>${otp?`<span class="auth-icon">${icon('shield-check')}</span>`:''}<h1>${otp?'One more step':t('welcome')}</h1><p>${otp?'Enter the OTP code to continue.':t('signin')}</p><form id="${otp?'otp-form':'login-form'}">${otp?field('otp','OTP code','text','', 'inputmode="numeric" maxlength="6" pattern="123456" placeholder="123456" autocomplete="one-time-code" required'):`${field('userid',t('userId'),'text','skagaruki',`placeholder="${esc(t('userIdPlaceholder'))}" autocomplete="username" required`)}${field('password',t('password'),'password','',`placeholder="${esc(t('passwordPlaceholder'))}" autocomplete="current-password" required`)}`}<p class="auth-hint">${otp?'Demo OTP code: 123456':'Use the registered Optima credentials.'}</p><p id="auth-error" role="alert"></p><button class="button primary full" type="submit">${otp?'Verify and continue':t('continue')} ${icon('arrow-right')}</button>${otp?'<button class="text-button full" type="button" data-action="resend">Show OTP code again</button>':''}</form><p class="auth-small">This prototype does not connect to the bank’s production sign-in service.</p></div></div></main>`;}
function overviewVideo(){return `<main class="intro-page" id="main" tabindex="-1"><video id="overview-video" class="intro-video" autoplay muted playsinline controls preload="auto" aria-label="Overview of the redesigned Optima employee portal"><source src="/assets/optima-web-overview.mp4" type="video/mp4">Your browser does not support this overview video.</video><div class="intro-shade" aria-hidden="true"></div><header class="intro-topbar"><img class="intro-logo" src="/assets/crdb-logo-white.png" alt="CRDB Bank"><button class="intro-skip" data-action="skip-overview">Skip overview ${icon('arrow-right')}</button></header><div class="intro-copy"><span>WELCOME TO THE NEW OPTIMA</span><h1>A clearer way to work together.</h1><p>The dashboard will open automatically when the overview finishes.</p></div></main>`;}
function finishOverview(){if(location.hash==='#intro'){navigate('dashboard');toast(`Welcome, ${currentUser.first}.`);}}

function render(){route=parseRoute();document.title='OPTIMA - I play my part, We win together.';$('#app').innerHTML=['signin','verify'].includes(route.view)?authView(route.view==='verify'):route.view==='intro'?overviewVideo():shell(route.view==='dashboard'?dashboard():route.view==='module'||route.view==='documents'?listing():route.view==='compose'?formView():route.view==='document'?documentView():notFound());translatePage($('#app'),language);icons();if(route.view==='intro'){const video=$('#overview-video');video.addEventListener('ended',finishOverview,{once:true});if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)video.pause();else video.play().catch(()=>{});}}
function openMemoTemplates(){modal('Start an internal memo',`<p class="dialog-intro">Choose a prepared template or begin with a blank memo.</p><div class="template-options"><button data-action="choose-template" data-template=""><span class="doc-icon">${icon('file-plus-2')}</span><span><strong>Blank memo</strong><small>Start with an empty document.</small></span>${icon('chevron-right')}</button>${MEMO_TEMPLATES.map(item=>`<button data-action="choose-template" data-template="${item.id}"><span class="doc-icon">${icon('file-check-2')}</span><span><strong>${esc(item.title)}</strong><small>${esc(item.to)}</small></span>${icon('chevron-right')}</button>`).join('')}</div>`,'create-dialog');}
function openCreate(id){if(id==='memo'){openMemoTemplates();return;}if(id){navigate('compose/'+id);return;}modal('What would you like to create?',`<p class="dialog-intro">Choose a document type to get started.</p><div class="create-options">${MODULES.filter(m=>!['invoices','duties'].includes(m.id)).map(m=>`<button data-action="choose-create" data-module="${m.id}"><span class="doc-icon">${icon(m.icon)}</span><span><strong>${m.name}</strong><small>${m.desc}</small></span>${icon('chevron-right')}</button>`).join('')}</div>`,'create-dialog');}
function searchResults(q=''){const mods=MODULES.filter(m=>m.name.toLowerCase().includes(q.toLowerCase())||translateText(m.name,language).toLowerCase().includes(q.toLowerCase()));const docs=selectRecords(records,{query:q}).slice(0,7);$('#search-results').innerHTML=`<p class="search-heading">Go to</p>${mods.slice(0,5).map(m=>`<a href="#module/${m.id}" data-action="search-result">${icon(m.icon)}<span>${m.name}</span>${icon('arrow-up-right')}</a>`).join('')}${docs.length?'<p class="search-heading">Documents</p>':''}${docs.map(r=>`<a href="#document/${r.id}" data-action="search-result">${icon('file-text')}<span>${esc(r.title)}<small>${esc(r.reference)}</small></span>${badge(r.status)}</a>`).join('')}${!mods.length&&!docs.length?empty('No matches found','Try a document title, reference or module name.'):''}`;translatePage($('#search-results'),language);icons();}
function openSearch(){modal('Search your workspace',`<label class="global-search">${icon('search')}<input id="global-query" placeholder="Search documents, references and services…" aria-label="Search workspace" autofocus></label><div id="search-results"></div>`,'search-dialog');searchResults();$('#global-query').focus();}
function saveRecord(intent){readDraft();const submit=intent==='submit',errors=validateDocument(draft,submit);document.querySelectorAll('.field-error').forEach(e=>e.textContent='');document.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));if(Object.keys(errors).length){$('#form-errors').hidden=false;$('#form-errors').textContent='Please complete the highlighted fields.';for(const[k,v]of Object.entries(errors)){const el=document.querySelector(`[data-error="${k}"]`);if(el)el.textContent=translateText(v,language);const control=k==='body'?$('#body-editor'):$(`[name="${k}"]`);control?.setAttribute('aria-invalid','true');}const first=Object.keys(errors)[0];(first==='body'?$('#body-editor'):$(`[name="${first}"]`))?.focus();return;}
 const status=submit?(draft.module==='certificates'?'Approved':draft.module==='uniforms'?'Submitted':'In review'):'Draft';const saved={...draft,status,reference:draft.reference||`OPT-${new Date().getFullYear()}-${crypto.randomUUID().slice(0,6).toUpperCase()}`,date:draft.date||today(),history:[...draft.history,{action:submit?(draft.module==='certificates'?'Card created':status):'Draft saved',date:today(),by:currentUser.name}]};delete saved.edit;
 const at=records.findIndex(r=>r.id===saved.id);if(at>=0)records[at]=saved;else records.unshift(saved);const durable=persist();dirty=false;draft=null;navigate('document/'+saved.id);toast(durable?(submit?(saved.module==='certificates'?'Thank you card saved in your preview.':'Submitted in your preview workspace.'):'Draft saved. You can come back to it anytime.'):'Saved for this session only. Browser storage is unavailable.');}
function changeStatus(id,status,note=''){const index=records.findIndex(r=>r.id===id);if(index<0)return;try{records[index]=transition(records[index],status,note,today(),currentUser.name);const ok=persist();render();toast(ok?`Document ${status.toLowerCase()} in your preview.`:'Change retained for this session only.');}catch(e){toast(e.message);}}

document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const {action,module:id,tab,id:recordId}=button.dataset;
 switch(action){
 case 'skip-main':e.preventDefault();$('#main')?.focus();break;
 case 'close-dialog':closeModal();break;
 case 'menu':$('.shell').classList.add('menu-open');button.setAttribute('aria-expanded','true');$('.sidebar a')?.focus();break;
 case 'close-menu':$('.shell').classList.remove('menu-open');$('.mobile-toggle')?.setAttribute('aria-expanded','false');$('.mobile-toggle')?.focus();break;
 case 'create':openCreate(id);break;
 case 'choose-create':closeModal();openCreate(id);break;
 case 'choose-template':{const template=button.dataset.template;closeModal();draft=null;navigate('compose/memo'+(template?'?template='+encodeURIComponent(template):''));break;}
 case 'search':openSearch();break;
 case 'search-result':closeModal();break;
 case 'dashboard-tab':dashboardTab=tab;render();break;
 case 'stat':case 'all-documents':navigate('documents?tab='+encodeURIComponent(tab));break;
 case 'sort':if(sort===button.dataset.sort)descending=!descending;else{sort=button.dataset.sort;descending=false;}refreshTable();break;
 case 'previous':page--;refreshTable();break;
 case 'next':page++;refreshTable();break;
 case 'filters':modal('Filter documents',`<form id="filter-form"><div class="field-grid">${field('start','From date','date',start)}${field('end','To date','date',end)}</div><label class="field"><span>Document status / action</span><select name="action">${['All','To review','Draft','In review','Returned','Approved','Received','Submitted','Archived'].map(s=>`<option value="${s}" ${actionFilter===s?'selected':''}>${s}</option>`).join('')}</select></label><p id="filter-error" role="alert"></p><div class="dialog-actions"><button class="button" type="button" data-action="clear-filters">Clear filters</button><button class="button primary" type="submit">Apply filters</button></div></form>`);break;
 case 'clear-filters':start='';end='';actionFilter='All';page=1;if(dialog.open)closeModal();render();break;
 case 'export':modal('Export this view',`<p class="dialog-intro">Export the ${currentRows().length} documents in your current filtered view.</p><div class="export-options"><button class="button" data-action="csv">${icon('file-spreadsheet')} Download CSV</button><button class="button" data-action="copy">${icon('copy')} Copy table</button><button class="button" data-action="print">${icon('printer')} Print / Save PDF</button></div>`);break;
 case 'csv':{const data=csv(currentRows());const url=URL.createObjectURL(new Blob(['\ufeff',data],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='optima-documents.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeModal();toast('Your CSV is ready.');break;}
 case 'copy':navigator.clipboard.writeText(csv(currentRows())).then(()=>{closeModal();toast('Table copied.');}).catch(()=>toast('Clipboard access is unavailable. Use Download CSV instead.'));break;
 case 'print':if(dialog.open)closeModal();window.print();break;
 case 'format':$('#body-editor').focus();document.execCommand(button.dataset.command,false,null);readDraft();dirty=true;break;
 case 'approve':modal('Approve this document?',`<p class="dialog-intro">This updates the document’s status in the local preview.</p><div class="dialog-actions"><button class="button" data-action="close-dialog">Cancel</button><button class="button primary" data-action="confirm-approve" data-id="${recordId}">Approve document</button></div>`);break;
 case 'confirm-approve':closeModal();changeStatus(recordId,'Approved');break;
 case 'return':modal('Return with feedback',`<form id="return-form" data-id="${recordId}"><label class="field"><span>What needs to change?</span><textarea name="feedback" rows="5" required placeholder="Give the author clear, useful feedback."></textarea></label><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancel</button><button class="button primary" type="submit">Return document</button></div></form>`);break;
 case 'archive':changeStatus(recordId,'Archived');break;
 case 'withdraw':modal('Withdraw to draft?',`<p class="dialog-intro">The document will leave the review queue so you can edit it.</p><div class="dialog-actions"><button class="button" data-action="close-dialog">Cancel</button><button class="button primary" data-action="confirm-withdraw" data-id="${recordId}">Withdraw to draft</button></div>`);break;
 case 'confirm-withdraw':closeModal();changeStatus(recordId,'Draft');break;
 case 'notifications':{const list=records.filter(r=>r.status==='To review');modal('Your attention is needed',`<p class="dialog-intro">${list.length} documents are waiting for your review.</p><div class="notification-list">${list.map(r=>`<a href="#document/${r.id}" data-action="search-result">${icon(moduleBy(r.module).icon)}<span><strong>${esc(r.title)}</strong><small>${esc(r.owner)} · ${moduleBy(r.module).name}</small></span>${icon('chevron-right')}</a>`).join('')||empty('You’re all caught up','No documents need your review.')}</div>`);break;}
 case 'profile':modal('Your profile',`<div class="profile-intro">${avatar(currentUser,true)}<div><h3>${esc(currentUser.name)}</h3><p>${esc(currentUser.role)}</p></div></div><dl class="profile-details"><dt>Department</dt><dd>${esc(currentUser.department)}</dd><dt>Email</dt><dd>${esc(currentUser.email)}</dd><dt>User ID</dt><dd>${esc(currentUser.id)}</dd><dt>Access</dt><dd>Employee prototype</dd></dl><div class="dialog-actions"><button class="button" data-action="signin">${icon('log-out')} Sign out</button><button class="button primary" data-action="close-dialog">Done</button></div>`);break;
 case 'signin':sessionStorage.removeItem('optima-user');currentUser=DEFAULT_USER;if(dialog.open)closeModal();navigate('signin');break;
 case 'language':modal(t('chooseLanguage'),`<div class="language-options"><button class="${language==='en'?'selected':''}" data-action="choose-language" data-language="en"><span><strong>English</strong><small>English</small></span>${language==='en'?icon('check'):''}</button><button class="${language==='sw'?'selected':''}" data-action="choose-language" data-language="sw"><span><strong>Kiswahili</strong><small>Swahili</small></span>${language==='sw'?icon('check'):''}</button><button class="${language==='fr'?'selected':''}" data-action="choose-language" data-language="fr"><span><strong>Français</strong><small>French</small></span>${language==='fr'?icon('check'):''}</button></div>`);break;
 case 'choose-language':language=button.dataset.language;localStorage.setItem('optima-language',language);document.documentElement.lang=languageCode(language);closeModal();render();toast(language==='sw'?'Lugha imebadilishwa kuwa Kiswahili.':language==='fr'?'Langue changée en français.':'Language changed to English.');break;
 case 'theme':theme=theme==='dark'?'light':'dark';localStorage.setItem('optima-theme',theme);document.documentElement.dataset.theme=theme;render();toast(theme==='dark'?t('dark'):t('light'));break;
 case 'resend':toast('Demo OTP code: 123456. No message is sent.');break;
 case 'skip-overview':finishOverview();break;
 case 'help':modal('A little help, when you need it',`<div class="help-content"><h3>Create and save</h3><p>Choose a document type, complete the details and save a draft. Submit it when you’re ready for review.</p><h3>Follow your work</h3><p>Use status tabs to find drafts, returned documents and items in review. Open a document to see its progress.</p><h3>Find things faster</h3><p>Use the search icon to find documents and services, then refine lists with filters.</p><h3>Review the sign-in experience</h3><p>Sign out from your profile. Use skagaruki with the password 1234 and demo OTP code 123456.</p></div>`);break;
 case 'about':modal('About this design preview',`<div class="help-content"><p>A reimagined Optima experience based on the supplied employee portal screenshots.</p><p>Documents and status changes stay in this browser. No approvals, messages or uploads go to the bank. Sample data illustrates how the screens work.</p><p>The original portal’s authentication, role permissions and integrations require connection before production use.</p><button class="button" data-action="reset">${icon('rotate-ccw')} Reset sample workspace</button></div>`);break;
 case 'reset':modal('Reset your preview workspace?',`<p class="dialog-intro">This removes documents you created in this preview and restores the sample data.</p><div class="dialog-actions"><button class="button" data-action="close-dialog">Cancel</button><button class="button danger" data-action="confirm-reset">Reset sample workspace</button></div>`);break;
 case 'confirm-reset':records=seeds();persist();dirty=false;draft=null;closeModal();if(location.hash==='#dashboard')render();else navigate('dashboard');toast('Sample workspace reset.');break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='table-query'){query=e.target.value;page=1;refreshTable();}if(e.target.id==='global-query')searchResults(e.target.value);if(e.target.closest('#document-form')){readDraft();dirty=true;$('#save-status').innerHTML=icon('circle-dot')+' '+translateText('Unsaved changes',language);if(e.target.id==='body-editor')$('#word-count').textContent=e.target.innerText.trim().split(/\s+/).filter(Boolean).length+' '+translateText('words',language);icons();}});
document.addEventListener('change',e=>{if(e.target.id==='page-size'){pageSize=Number(e.target.value);page=1;refreshTable();}if(e.target.id==='attachment'){const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){$('#attachment-error').textContent='Choose a file smaller than 10 MB.';e.target.value='';return;}$('#attachment-error').textContent='';draft.attachment=file.name;$('#attachment-name').textContent=file.name;dirty=true;}});
document.addEventListener('paste',e=>{if(e.target.id==='body-editor'){e.preventDefault();const text=e.clipboardData.getData('text/plain');document.execCommand('insertText',false,text);}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;
 if(form.id==='document-form')saveRecord(e.submitter?.value||'draft');
 if(form.id==='filter-form'){const data=new FormData(form);const a=data.get('start'),b=data.get('end');if(a&&b&&a>b){$('#filter-error').textContent='The end date must be on or after the start date.';return;}start=a;end=b;actionFilter=data.get('action');page=1;closeModal();render();}
 if(form.id==='return-form'){const note=new FormData(form).get('feedback').trim();if(!note)return;const id=form.dataset.id;closeModal();changeStatus(id,'Returned',note);}
 if(form.id==='login-form'){const f=new FormData(form),user=authenticate(f.get('userid'),f.get('password'));if(!user){$('#auth-error').textContent=language==='sw'?'Kitambulisho au nenosiri si sahihi.':language==='fr'?'L’identifiant ou le mot de passe est incorrect.':'The user ID or password is incorrect.';return;}pendingUser=user;sessionStorage.setItem('optima-pending-user',user.id);navigate('verify');}
 if(form.id==='otp-form'){if(new FormData(form).get('otp')!=='123456'){$('#auth-error').textContent=language==='sw'?'Tumia namba ya majaribio 123456.':language==='fr'?'Utilisez le code de démonstration 123456.':'Use the prototype code 123456.';return;}currentUser=pendingUser||DEFAULT_USER;sessionStorage.setItem('optima-user',JSON.stringify(currentUser));sessionStorage.removeItem('optima-pending-user');navigate('intro');}
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}if(e.key==='Escape'&&$('.shell')?.classList.contains('menu-open')){$('.shell').classList.remove('menu-open');$('.mobile-toggle')?.setAttribute('aria-expanded','false');$('.mobile-toggle')?.focus();}if(e.key==='Tab'&&$('.shell')?.classList.contains('menu-open')){const items=[...document.querySelectorAll('.sidebar a,.sidebar button')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-action="format"]'))e.preventDefault();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{if(dirty&&route?.view==='compose'){if(!confirm(translateText('Leave this document without saving your changes?',language))){history.replaceState(null,'',oldHash||'#dashboard');return;}dirty=false;draft=null;}oldHash=location.hash;page=1;query='';start='';end='';actionFilter='All';if(dialog.open)closeModal();render();$('#main')?.focus();window.scrollTo({top:0});});
render();
